import{_ as t,c as d,o as r,a4 as e}from"./chunks/framework.BYxathSa.js";const p=JSON.parse('{"title":"Q9：Grid 布局与 Flex 布局的区别","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q9.md","filePath":"frontend/q9.md","lastUpdated":null}'),o={name:"frontend/q9.md"},a=e('<h1 id="q9-grid-布局与-flex-布局的区别" tabindex="-1">Q9：Grid 布局与 Flex 布局的区别 <a class="header-anchor" href="#q9-grid-布局与-flex-布局的区别" aria-label="Permalink to &quot;Q9：Grid 布局与 Flex 布局的区别&quot;">​</a></h1><table><thead><tr><th>特性</th><th>Flexbox</th><th>Grid</th></tr></thead><tbody><tr><td><strong>维度</strong></td><td>一维布局（行或列）</td><td>二维布局（行与列同时）</td></tr><tr><td><strong>控制力</strong></td><td>基于轴线，内容驱动</td><td>基于网格，固定或弹性轨道</td></tr><tr><td><strong>适用场景</strong></td><td>导航栏、组件内元素排列、居中</td><td>复杂页面整体布局、等分网格、重叠元素</td></tr><tr><td><strong>对齐</strong></td><td>主/交叉轴对齐</td><td>行/列两条轴都提供 <code>justify/align</code> 属性</td></tr><tr><td><strong>重叠</strong></td><td>较难实现元素重叠</td><td>可以使用 <code>grid-area</code> 轻松实现重叠</td></tr></tbody></table><p>简单说：<strong>Flex 擅长处理一个方向上的排列和空间分配，Grid 擅长处理同时有行和列的二维布局</strong>。两者可以互补，经常在组件内部用 Flex，在页面大框架用 Grid。</p>',3),n=[a];function s(i,l,_,c,h,g){return r(),d("div",null,n)}const x=t(o,[["render",s]]);export{p as __pageData,x as default};
